mapper.select:
SELECT pp.promotion_id, pp.merchant_id, pp.type, pp.name, pp.discount, pp.min_amount, pp.discount_amount, pp.start_time, pp.end_time, pp.status, pp.description, pp.create_time, pp.update_time, COUNT(pr.product_id) as product_count FROM product_promotion pp LEFT JOIN promotion_product pr ON pp.promotion_id = pr.promotion_id
AND pp.merchant_id = #{merchantId}
AND pp.status = #{status}
GROUP BY pp.promotion_id ORDER BY pp.create_time DESC
